ON CONFLICT (id) DO NOTHING;

-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('1e79a3cb-7f25-5070-ba52-fd625f12f055'::uuid, 'a3040428-6fe1-5f4f-afeb-12afaa7f2572'::uuid, 'Combien de joueurs une équipe de football aligne-t-elle sur le terrain, gardien compris ?', 'mcq', '["7","11","9","12"]'::jsonb, 1, 'Une équipe de football compte 11 joueurs, dont le gardien.', 1),
    ('e334d0ce-883d-5daf-93c1-d1a186fd1336'::uuid, 'a3040428-6fe1-5f4f-afeb-12afaa7f2572'::uuid, 'Combien de remplacements une équipe peut-elle faire dans un match, depuis la règle permanente de 2022 ?', 'mcq', '["3","1","8","5"]'::jsonb, 3, 'Depuis 2022, la règle permanente autorise 5 remplacements par équipe.', 2),
    ('ff05159d-4958-5ded-b5b4-ec961286a48e'::uuid, 'a3040428-6fe1-5f4f-afeb-12afaa7f2572'::uuid, 'Être en position de hors-jeu est toujours une faute sanctionnée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La position seule ne suffit pas : il faut aussi participer au jeu au moment de la passe pour être sanctionné.', 3),
    ('ea615fbc-000f-50cd-971e-b7e5c2b2b4f6'::uuid, 'a3040428-6fe1-5f4f-afeb-12afaa7f2572'::uuid, 'Par rapport à quoi est jugée la position de hors-jeu d’un attaquant ?', 'mcq', '["Le gardien seul","Le numéro du maillot","Le ballon et l’avant-dernier défenseur","Le milieu de terrain"]'::jsonb, 2, 'L’attaquant doit être plus près de la ligne de but que le ballon et que l’avant-dernier défenseur adverse.', 4),
    ('461e1c20-d491-56ff-ab43-cd7f2ba2f76d'::uuid, 'a3040428-6fe1-5f4f-afeb-12afaa7f2572'::uuid, 'Dans quelle situation le hors-jeu est-il impossible ?', 'mcq', '["Sur une touche","Sur une passe longue dans la surface","Sur un tir cadré","Sur un centre venu de l’aile"]'::jsonb, 0, 'Il n’y a jamais de hors-jeu directement sur une touche, un corner ou un coup de pied de but.', 5),
    ('94d4be62-a944-58ef-a78c-31bb7d5d5e6a'::uuid, 'a3040428-6fe1-5f4f-afeb-12afaa7f2572'::uuid, 'À quelle distance du but se tire un penalty ?', 'mcq', '["6 mètres","16 mètres","9 mètres","11 mètres"]'::jsonb, 3, 'Le penalty se tire à 11 mètres, face au gardien seul.', 6),
    ('87e9d384-fc51-5a1c-8321-d823700ab22b'::uuid, 'a3040428-6fe1-5f4f-afeb-12afaa7f2572'::uuid, 'Un joueur reçoit deux cartons jaunes dans le même match. Que se passe-t-il ?', 'mcq', '["Le match est arrêté","Il est expulsé, comme avec un carton rouge","Il reçoit un simple avertissement de plus","Il sort et son équipe peut le remplacer"]'::jsonb, 1, 'Deux jaunes équivalent à un rouge : le joueur est expulsé et personne ne le remplace.', 7),
    ('c149fafd-63c6-51fe-8026-0ee554f13efc'::uuid, 'a3040428-6fe1-5f4f-afeb-12afaa7f2572'::uuid, 'Un joueur est dans sa propre moitié de terrain quand on lui passe le ballon. Peut-il être hors-jeu ?', 'mcq', '["Oui, s’il est le plus avancé","Oui, si le gardien est sorti","Non, jamais dans sa moitié de terrain","Oui, si un défenseur est derrière lui"]'::jsonb, 2, 'Dans sa propre moitié de terrain, on ne peut pas être hors-jeu, quelle que soit la position des défenseurs.', 8),
    ('b40ed6da-28c8-5e3c-8e82-94318f96085d'::uuid, 'a3040428-6fe1-5f4f-afeb-12afaa7f2572'::uuid, 'Le gardien adverse compte parmi les défenseurs pour juger un hors-jeu.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le gardien est un défenseur comme les autres : il peut être l’avant-dernier ou le dernier adversaire.', 9),
    ('24b14d6b-c443-5124-adc9-de95cd0f087d'::uuid, 'a3040428-6fe1-5f4f-afeb-12afaa7f2572'::uuid, 'La VAR a été utilisée pour la première fois à une Coupe du monde en…', 'mcq', '["2018","1998","2010","2022"]'::jsonb, 0, 'L’assistance vidéo à l’arbitrage a fait son entrée en Coupe du monde en 2018.', 10),
    ('58026d8b-89e9-5948-8f45-02c7e02e6a16'::uuid, 'a3040428-6fe1-5f4f-afeb-12afaa7f2572'::uuid, 'La VAR remplace l’arbitre sur le terrain, qui n’a plus le dernier mot.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La VAR conseille l’arbitre sur certaines décisions importantes, mais c’est lui qui décide.', 11),
    ('57121579-7220-5783-b044-71099d60f6a4'::uuid, 'e1c3a0a5-9124-5861-9a67-02da09169ee3'::uuid, 'À quelle hauteur se trouve le panier de basket ?', 'mcq', '["3,50 mètres","3,05 mètres","2,43 mètres","2,80 mètres"]'::jsonb, 1, 'Le panier est fixé à 3,05 mètres du sol, partout dans le monde.', 1),
    ('353ee478-f4b5-53eb-b0f2-9662716eb54a'::uuid, 'e1c3a0a5-9124-5861-9a67-02da09169ee3'::uuid, 'Combien de joueurs une équipe de basket aligne-t-elle sur le terrain ?', 'mcq', '["6","7","11","5"]'::jsonb, 3, 'Chaque équipe a 5 joueurs sur le terrain.', 2),
    ('88653f8f-4f30-5460-a817-d1ac7135eb2a'::uuid, 'e1c3a0a5-9124-5861-9a67-02da09169ee3'::uuid, 'Combien vaut un lancer franc réussi ?', 'mcq', '["3 points","0 point","1 point","2 points"]'::jsonb, 2, 'Un lancer franc vaut 1 point, un tir normal 2 et un tir derrière la ligne 3.', 3),
    ('cc0452ee-8e06-59d0-ad28-e75670a3dab1'::uuid, 'e1c3a0a5-9124-5861-9a67-02da09169ee3'::uuid, 'Que signifie « marcher » au basket ?', 'mcq', '["Faire plus de deux appuis avec le ballon sans dribbler","Marcher sans le ballon","Dribbler avec les deux mains","Sortir du terrain"]'::jsonb, 0, 'Tenir le ballon et avancer au-delà des deux appuis sans le faire rebondir est une violation : le ballon passe à l’adversaire.', 4),
    ('f2f2ec49-9dcc-55e5-b564-58c60b28ad0f'::uuid, 'e1c3a0a5-9124-5861-9a67-02da09169ee3'::uuid, 'Dans quel délai une équipe doit-elle tirer après avoir récupéré le ballon ?', 'mcq', '["8 secondes","3 secondes","60 secondes","24 secondes"]'::jsonb, 3, 'Les 24 secondes obligent l’équipe à tenter sa chance avant la fin du chronomètre.', 5),
    ('e72df5bb-38ff-5f90-9662-db81690fb0c0'::uuid, 'e1c3a0a5-9124-5861-9a67-02da09169ee3'::uuid, 'Quelle règle impose de franchir la ligne médiane en 8 secondes ?', 'mcq', '["Le lancer franc","La règle des 8 secondes","La règle des 3 secondes","La reprise de dribble"]'::jsonb, 1, 'Après avoir récupéré le ballon dans son camp, on a 8 secondes pour passer la ligne médiane.', 6),
    ('944751ed-f38a-5548-a0b3-06d6a4cd54d6'::uuid, 'e1c3a0a5-9124-5861-9a67-02da09169ee3'::uuid, 'Un match de la NBA dure 4 quarts-temps de 12 minutes, contre 10 minutes en FIBA.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La NBA joue 4 × 12 minutes, alors que les règles FIBA donnent 4 × 10 minutes.', 7),
    ('f8279686-47d8-52ce-9346-5ca1cdd2a28e'::uuid, 'e1c3a0a5-9124-5861-9a67-02da09169ee3'::uuid, 'Après combien de fautes personnelles un joueur est-il exclu en règles FIBA ?', 'mcq', '["6","10","5","3"]'::jsonb, 2, 'En FIBA, la cinquième faute personnelle exclut le joueur (la sixième en NBA).', 8),
    ('7ca78970-8e29-526c-95cc-1e8fb63ce18a'::uuid, 'e1c3a0a5-9124-5861-9a67-02da09169ee3'::uuid, 'La ligne à trois points est exactement à la même distance en FIBA et en NBA.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est à 6,75 m en FIBA et à 7,24 m en NBA.', 9),
    ('349e4849-76e9-5e82-877a-d9f72a4a94c2'::uuid, 'e1c3a0a5-9124-5861-9a67-02da09169ee3'::uuid, 'Un joueur arrête de dribbler, puis redémarre son dribble. Que se passe-t-il ?', 'mcq', '["C’est une reprise de dribble : le ballon passe à l’adversaire","C’est un panier de plus","C’est autorisé","C’est un lancer franc pour lui"]'::jsonb, 0, 'Une fois le dribble arrêté, on doit passer ou tirer ; redribbler est une faute de reprise de dribble.', 10),
    ('4a8ded5b-34bc-5684-9ac5-0583dee0d3a9'::uuid, 'e1c3a0a5-9124-5861-9a67-02da09169ee3'::uuid, 'Un attaquant peut rester trois minutes dans la raquette sans problème.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La règle des 3 secondes l’interdit : au-delà, le ballon passe à l’adversaire.', 11),
    ('d14efcb6-81c8-51d6-b5a4-1ca14a51fbdf'::uuid, '3f1a6a07-aaff-5cf4-a1df-7158fd4c659a'::uuid, 'Combien de joueurs, gardien compris, une équipe de handball a-t-elle sur le terrain ?', 'mcq', '["5","7","6","11"]'::jsonb, 1, 'Une équipe de handball aligne 6 joueurs de champ et un gardien, soit 7.', 1),
    ('b887a1ac-c3b5-515b-b0ab-832992a8805f'::uuid, '3f1a6a07-aaff-5cf4-a1df-7158fd4c659a'::uuid, 'Combien de pas peut-on faire avec le ballon en main au handball ?', 'mcq', '["1","5","Autant qu’on veut","3"]'::jsonb, 3, 'On ne fait pas plus de trois pas avec le ballon sans dribbler.', 2),
    ('a1acb40b-7f55-57ff-83bf-88392238025c'::uuid, '3f1a6a07-aaff-5cf4-a1df-7158fd4c659a'::uuid, 'Qui a le droit d’entrer dans la zone des 6 mètres au handball ?', 'mcq', '["Les attaquants","Les remplaçants","Seulement le gardien","Tous les joueurs"]'::jsonb, 2, 'La zone des 6 mètres est réservée au gardien de but.', 3),
    ('2e8573bd-6206-5037-864f-1f454230186f'::uuid, '3f1a6a07-aaff-5cf4-a1df-7158fd4c659a'::uuid, 'Que se passe-t-il quand un joueur de handball reçoit une exclusion de 2 minutes ?', 'mcq', '["Il sort 2 minutes et son équipe joue à six","Il est exclu du match pour toujours","Il reste mais perd un point","Son équipe joue à huit"]'::jsonb, 0, 'Pendant deux minutes, l’équipe reste en infériorité numérique.', 4),
    ('8ecd2a13-e7eb-59c2-b4e9-fab533b0f0e0'::uuid, '3f1a6a07-aaff-5cf4-a1df-7158fd4c659a'::uuid, 'Le jeu passif est une règle qui oblige une équipe à…', 'mcq', '["défendre en zone","changer de gardien","marquer deux fois","tenter vraiment d’attaquer"]'::jsonb, 3, 'Si une équipe ne cherche pas à marquer, l’arbitre signale le jeu passif et elle doit tirer vite.', 5),
    ('bd0600a0-5677-5b96-a065-7b4179484836'::uuid, '3f1a6a07-aaff-5cf4-a1df-7158fd4c659a'::uuid, 'À partir de combien de points un set de volley est-il gagné, avec 2 points d’écart ?', 'mcq', '["30","25","15","21"]'::jsonb, 1, 'Un set se gagne à 25 points, avec au moins 2 points d’écart ; seul le 5e set va à 15.', 6),
    ('9debf50f-e98c-55c9-bb4e-0abdce0910f5'::uuid, '3f1a6a07-aaff-5cf4-a1df-7158fd4c659a'::uuid, 'Chaque équipe de volley peut toucher le ballon au maximum trois fois avant de le renvoyer.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La règle des trois touches maximum oblige à construire l’attaque.', 7),
    ('c97ccc3e-0867-5785-b295-1e08867495f9'::uuid, '3f1a6a07-aaff-5cf4-a1df-7158fd4c659a'::uuid, 'Que peut faire le libéro, en maillot de couleur différente ?', 'mcq', '["Servir toujours","Arbitrer","Défendre seulement","Attaquer au filet"]'::jsonb, 2, 'Le libéro est spécialisé dans la défense : il ne peut ni attaquer ni servir.', 8),
    ('cebdfbd2-ee70-53f4-ae8f-69691d97e0b5'::uuid, '3f1a6a07-aaff-5cf4-a1df-7158fd4c659a'::uuid, 'À quelle hauteur est le filet de volley pour les hommes ?', 'mcq', '["2,43 m","2,24 m","3,05 m","1,80 m"]'::jsonb, 0, '2,43 m pour les hommes, 2,24 m pour les femmes.', 9),
    ('fa0d0a0c-656b-5856-9bfb-7273da1b57b7'::uuid, '3f1a6a07-aaff-5cf4-a1df-7158fd4c659a'::uuid, 'En volley, la rotation permet à tous les joueurs de servir.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'À chaque récupération du service, les joueurs tournent d’une place : tout le monde passe au service.', 10),
    ('9b8c2e40-c32f-55ee-ae3b-a02d3c7afc2d'::uuid, '3f1a6a07-aaff-5cf4-a1df-7158fd4c659a'::uuid, 'En quelle année l’équipe de France masculine de handball a-t-elle remporté l’or olympique pour la première fois ?', 'mcq', '["2016","2008","1992","2000"]'::jsonb, 1, 'Les Experts ont gagné l’or olympique à Pékin en 2008, puis en 2012 et en 2020.', 11),
    ('164c5793-d285-5c29-b7be-047c518671b3'::uuid, 'adeb6551-31a2-5e05-be3f-8d0fc53e6396'::uuid, 'Combien de joueurs compte une équipe de rugby à XV ?', 'mcq', '["7","11","13","15"]'::jsonb, 3, 'XV, c’est 15 en chiffres romains : 15 joueurs par équipe.', 1),
    ('dafe2ae9-840d-51ef-b004-6b02f332838e'::uuid, 'adeb6551-31a2-5e05-be3f-8d0fc53e6396'::uuid, 'Combien de temps dure chaque mi-temps au rugby à XV ?', 'mcq', '["30 minutes","7 minutes","40 minutes","45 minutes"]'::jsonb, 2, 'Un match de rugby à XV se joue en deux mi-temps de 40 minutes.', 2),
    ('d21b95ff-3588-5007-905a-42e3dd1e4c38'::uuid, 'adeb6551-31a2-5e05-be3f-8d0fc53e6396'::uuid, 'Dans quelle direction peut-on passer le ballon au rugby ?', 'mcq', '["Vers l’arrière ou sur le côté","Vers l’avant seulement","Dans toutes les directions","Vers le haut seulement"]'::jsonb, 0, 'La passe vers l’avant est un en-avant : on passe en arrière ou latéralement.', 3),
    ('f42ffffc-7b51-5bee-bd71-378bcbf4e1cb'::uuid, 'adeb6551-31a2-5e05-be3f-8d0fc53e6396'::uuid, 'Que vaut un essai au rugby à XV ?', 'mcq', '["3 points","2 points","7 points","5 points"]'::jsonb, 3, 'L’essai vaut 5 points ; la transformation en ajoute 2.', 4),
    ('0f4893b6-4315-51f2-a80b-bea0571e3b1f'::uuid, 'adeb6551-31a2-5e05-be3f-8d0fc53e6396'::uuid, 'Que se passe-t-il après un en-avant ?', 'mcq', '["Une touche pour la même équipe","Une mêlée pour l’équipe adverse","Un essai de pénalité","Un carton rouge"]'::jsonb, 1, 'L’en-avant se sanctionne par une mêlée au profit des adversaires.', 5),
    ('6a4b099a-35bc-5ba3-bf3c-48f984ba315d'::uuid, 'adeb6551-31a2-5e05-be3f-8d0fc53e6396'::uuid, 'Où le plaquage doit-il se faire ?', 'mcq', '["À la tête","Peu importe où","Sous la ligne des épaules","Au niveau du cou"]'::jsonb, 2, 'Plaquer au cou ou à la tête est interdit : on plaque sous la ligne des épaules.', 6),
    ('1d9a107f-6415-57d8-bad7-ca4e3beb1185'::uuid, 'adeb6551-31a2-5e05-be3f-8d0fc53e6396'::uuid, 'Une pénalité réussie entre les poteaux rapporte 3 points.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La pénalité comme le drop valent 3 points.', 7),
    ('03a1bc56-842a-56b3-89af-00fcc916ec35'::uuid, 'adeb6551-31a2-5e05-be3f-8d0fc53e6396'::uuid, 'Que fait-on pendant une touche ?', 'mcq', '["On lance le ballon entre deux lignes de joueurs","On tire un penalty","On forme une mêlée","On change de camp"]'::jsonb, 0, 'Un coéquipier lance le ballon entre les deux lignes, et les joueurs sautent pour l’attraper.', 8),
    ('06082891-5bd5-59e4-b3d9-773cd57f7092'::uuid, 'adeb6551-31a2-5e05-be3f-8d0fc53e6396'::uuid, 'Au rugby, qui peut discuter avec l’arbitre ?', 'mcq', '["Le public du stade","Le capitaine, avec respect","Tous les joueurs à voix haute","Les supporters"]'::jsonb, 1, 'On appelle l’arbitre « Monsieur » et seul le capitaine lui parle.', 9),
    ('28599100-2f5a-5999-9a98-f00554259102'::uuid, 'adeb6551-31a2-5e05-be3f-8d0fc53e6396'::uuid, 'Le rugby à 7 oppose deux équipes de 7 joueurs sur des matchs de 2 × 7 minutes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la version courte et rapide du rugby, qui a donné l’or à la France à Paris 2024.', 10),
    ('2edc92b6-6bfe-5b94-9f84-27c638b9e972'::uuid, 'adeb6551-31a2-5e05-be3f-8d0fc53e6396'::uuid, 'Un joueur lance le ballon vers l’avant à son coéquipier. L’arbitre siffle…', 'mcq', '["un essai","une transformation","un drop","un en-avant"]'::jsonb, 3, 'Toute passe vers l’avant est un en-avant, quelle que soit la distance.', 11),
    ('e08f3028-2d08-5cea-a52c-cd171f0b8e0f'::uuid, 'adeb6551-31a2-5e05-be3f-8d0fc53e6396'::uuid, 'Le ruck est un rassemblement de joueurs autour d’un ballon posé au sol.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après un plaquage, des joueurs se lient debout au-dessus du ballon au sol pour le protéger ou le récupérer.', 12),
    ('47ba1f24-6890-5291-9443-62d7563269ad'::uuid, '1484426b-bfc8-5aa5-b7ca-adabd7504ef3'::uuid, 'Quels sont les points d’un jeu au tennis ?', 'mcq', '["10, 20, 30","5, 10, 15","15, 30, 40","1, 2, 3"]'::jsonb, 2, 'Les points d’un jeu se comptent 15, 30 et 40, puis le jeu.', 1),
    ('d4d74d0e-765c-556f-be90-06f26f127966'::uuid, '1484426b-bfc8-5aa5-b7ca-adabd7504ef3'::uuid, 'Que se passe-t-il quand le score d’un jeu est de 40 partout ?', 'mcq', '["C’est l’égalité : il faut deux points d’écart","Le jeu est rejoué","Le premier serveur gagne","Le set se termine"]'::jsonb, 0, 'À l’égalité, un joueur doit gagner deux points de suite (avantage puis jeu).', 2),
    ('ca198471-d1ad-54ab-b8a4-ec6d03250637'::uuid, '1484426b-bfc8-5aa5-b7ca-adabd7504ef3'::uuid, 'Combien de jeux faut-il gagner pour un set, avec 2 jeux d’écart ?', 'mcq', '["4","10","3","6"]'::jsonb, 3, 'On gagne un set à 6 jeux, avec 2 jeux d’écart.', 3),
    ('2425f0e0-0eb6-5560-84a1-8b84cbba2fbd'::uuid, '1484426b-bfc8-5aa5-b7ca-adabd7504ef3'::uuid, 'Quand joue-t-on un tie-break ?', 'mcq', '["Au premier set","À 6 jeux partout","À 40 partout","À 3 sets partout"]'::jsonb, 1, 'À 6-6 dans un set, on joue un tie-break pour décider du gagnant du set.', 4),
    ('d8568241-74ef-56e7-a083-30ed505d306f'::uuid, '1484426b-bfc8-5aa5-b7ca-adabd7504ef3'::uuid, 'Combien de points faut-il pour gagner un tie-break ?', 'mcq', '["10","3","7, avec 2 points d’écart","5"]'::jsonb, 2, 'Le tie-break se gagne à 7 points avec 2 points d’écart.', 5),
    ('0b24b8e5-6ba6-5119-831e-81d4ebf02a5d'::uuid, '1484426b-bfc8-5aa5-b7ca-adabd7504ef3'::uuid, 'Combien de balles de service a-t-on pour chaque point ?', 'mcq', '["Deux","Une","Trois","Quatre"]'::jsonb, 0, 'Après une première faute, on a une seconde balle ; deux fautes font une double faute.', 6),
    ('9fd1fc0a-72a7-5294-8280-fcb60e4027e1'::uuid, '1484426b-bfc8-5aa5-b7ca-adabd7504ef3'::uuid, 'Un « let » au service signifie…', 'mcq', '["que la balle est trop haute","qu’on rejoue le service","que le point est perdu","que le jeu est gagné"]'::jsonb, 1, 'Quand le service touche le filet et tombe dans le bon carré, le service est rejoué.', 7),
    ('2f332dcc-8333-5224-8fac-1ef8b4ce2867'::uuid, '1484426b-bfc8-5aa5-b7ca-adabd7504ef3'::uuid, 'Roland-Garros se joue sur terre battue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le tournoi de Roland-Garros se dispute sur terre battue, à Paris.', 8),
    ('87bbee84-42e5-5f81-aed0-69ac272f1c1b'::uuid, '1484426b-bfc8-5aa5-b7ca-adabd7504ef3'::uuid, 'Combien de fois Rafael Nadal a-t-il gagné Roland-Garros ?', 'mcq', '["7","10","20","14"]'::jsonb, 3, 'Rafael Nadal détient le record de 14 victoires à Roland-Garros.', 9),
    ('47b2b38b-8b15-57d1-bd6e-b61a74f05a37'::uuid, '1484426b-bfc8-5aa5-b7ca-adabd7504ef3'::uuid, 'Au badminton, un set se joue en 21 points avec 2 points d’écart.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le set se joue à 21 points avec 2 d’écart, plafonné à 30.', 10),
    ('36284c97-e855-553b-b605-31628ccd2b9a'::uuid, '1484426b-bfc8-5aa5-b7ca-adabd7504ef3'::uuid, 'Combien de sets faut-il gagner pour remporter un match de badminton ?', 'mcq', '["1","5","2","3"]'::jsonb, 2, 'Un match de badminton se joue au meilleur des trois sets : il faut en gagner 2.', 11),
    ('d042d885-7262-509d-8a4c-80e01de8ac9a'::uuid, '7863a5dd-cf54-5b17-b435-c2fd4f340a9d'::uuid, 'Quelle part de l’énergie dépensée par un muscle part en chaleur ?', 'mcq', '["Environ les trois quarts","Environ un dixième","Environ la moitié exactement","Presque rien"]'::jsonb, 0, 'Environ les trois quarts de l’énergie partent en chaleur et un quart seulement en mouvement.', 1),
    ('3dd35358-2a6f-5053-bf90-9ee45a22cad6'::uuid, '7863a5dd-cf54-5b17-b435-c2fd4f340a9d'::uuid, 'Autour de quelle température le corps cherche-t-il à rester ?', 'mcq', '["30 °C","42 °C","25 °C","37 °C"]'::jsonb, 3, 'Le corps tient autour de 37 °C : c’est la température où les organes fonctionnent bien.', 2),
    ('0e67c104-718b-54b5-a971-81c1326e3258'::uuid, '7863a5dd-cf54-5b17-b435-c2fd4f340a9d'::uuid, 'Qu’est-ce qui refroidit réellement le corps quand on transpire ?', 'mcq', '["La couleur de la peau","L’évaporation de la sueur","La quantité de sueur","Le sel dans la sueur"]'::jsonb, 1, 'L’eau qui s’évapore prend de la chaleur à la peau : c’est l’évaporation qui refroidit.', 3),
    ('f67a0be7-acd8-5c04-80ba-0d4f67d4cd84'::uuid, '7863a5dd-cf54-5b17-b435-c2fd4f340a9d'::uuid, 'Pourquoi rougit-on pendant un effort ?', 'mcq', '["Le sang devient plus rouge","La peau est abîmée","Les vaisseaux de la peau se dilatent pour évacuer la chaleur","Le cœur s’arrête un instant"]'::jsonb, 2, 'Les vaisseaux sous la peau s’élargissent : plus de sang arrive près de la surface et la chaleur s’échappe.', 4),
    ('21a9b335-88c3-5a07-a5dd-ef9ea1cef833'::uuid, '7863a5dd-cf54-5b17-b435-c2fd4f340a9d'::uuid, 'Quand faut-il boire pendant un effort ?', 'mcq', '["Avant d’avoir soif","Seulement quand on a soif","Jamais pendant l’effort","Après l’effort uniquement"]'::jsonb, 0, 'La soif arrive quand le manque d’eau a déjà commencé : on boit avant, par petites gorgées.', 5),
    ('8e72a698-a948-5420-8084-c3b27b3b7ecf'::uuid, '7863a5dd-cf54-5b17-b435-c2fd4f340a9d'::uuid, 'La sueur qui coule sans s’évaporer refroidit autant que celle qui s’évapore.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seule l’évaporation prend la chaleur de la peau ; une sueur qui coule ne refroidit presque pas.', 6),
    ('57471fab-beda-5c95-b290-22e170e6feb0'::uuid, '7863a5dd-cf54-5b17-b435-c2fd4f340a9d'::uuid, 'Pourquoi transpire-t-on davantage quand l’air est humide sans vent ?', 'mcq', '["Le soleil chauffe plus","La sueur s’évapore mal, alors le corps en produit plus","L’eau est plus chaude","On a moins de glandes"]'::jsonb, 1, 'L’air humide ralentit l’évaporation : le corps transpire plus pour compenser et se refroidit moins bien.', 7),
    ('90f5078f-8bd7-5f8a-80cf-761538b2a639'::uuid, '7863a5dd-cf54-5b17-b435-c2fd4f340a9d'::uuid, 'Combien de glandes sudoripares a-t-on environ sur la peau ?', 'mcq', '["20 à 40","200 à 400","2 à 4 milliards","2 à 4 millions"]'::jsonb, 3, 'On compte entre 2 et 4 millions de glandes qui fabriquent la sueur.', 8),
    ('957f467d-ff93-5936-a7eb-548d1330af24'::uuid, '7863a5dd-cf54-5b17-b435-c2fd4f340a9d'::uuid, 'Un élève a la peau très rouge et chaude, un mal de tête et des vertiges par forte chaleur. Que faire ?', 'mcq', '["Boire un grand verre d’eau glacée d’un coup","Mettre un pull pour transpirer plus","Arrêter l’effort, se mettre à l’ombre, se refroidir et prévenir un adulte","Continuer pour s’habituer"]'::jsonb, 2, 'Ce sont les signes d’un coup de chaleur : il faut stopper, refroidir le corps et faire appeler les secours si ça ne passe pas.', 9),
    ('d8996125-061a-5cc8-b557-fcabb1ca1f8f'::uuid, '7863a5dd-cf54-5b17-b435-c2fd4f340a9d'::uuid, 'On peut perdre 1 à 2 litres de sueur par heure lors d’un effort intense.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'À effort intense, la perte atteint un à deux litres par heure : d’où l’importance de s’hydrater.', 10),
    ('9239377c-292d-5832-8d70-12929eeb1ad6'::uuid, '7863a5dd-cf54-5b17-b435-c2fd4f340a9d'::uuid, 'Pourquoi s’habiller en couches est-il pratique pour le sport ?', 'mcq', '["On peut en enlever une quand on a chaud","Cela fait plus joli","On transpire moins","On court plus vite"]'::jsonb, 0, 'Les couches s’ajoutent ou s’enlèvent selon la température du corps, sans surchauffer ni se refroidir.', 11),
    ('f6138a45-4329-5301-a2a6-05d1b591a38b'::uuid, '036e6709-577e-5c26-a9e4-6d4368a3087a'::uuid, 'Quelle est la fréquence cardiaque d’un adulte au repos ?', 'mcq', '["10 à 20 battements par minute","150 à 180 battements par minute","300 battements par minute","60 à 80 battements par minute"]'::jsonb, 3, 'Au repos, le cœur d’un adulte bat 60 à 80 fois par minute.', 1),
    ('3a2ff9ce-0d73-52a0-b4cf-f8521a7bfa51'::uuid, '036e6709-577e-5c26-a9e4-6d4368a3087a'::uuid, 'Combien de litres de sang le cœur envoie-t-il par minute à l’effort ?', 'mcq', '["200 litres","20 à 25 litres","1 litre","5 litres"]'::jsonb, 1, 'Au repos il envoie environ 5 litres par minute, et jusqu’à 20 à 25 à l’effort.', 2),
    ('34d2f090-6445-5269-abbf-e57e6cff68b6'::uuid, '036e6709-577e-5c26-a9e4-6d4368a3087a'::uuid, 'Comment estime-t-on la fréquence cardiaque maximale ?', 'mcq', '["L’âge multiplié par 10","60 moins l’âge","220 moins l’âge","100 plus l’âge"]'::jsonb, 2, 'La formule 220 − âge donne une approximation, pas une mesure exacte.', 3),
    ('7724c287-8089-595d-a9be-5bf124437654'::uuid, '036e6709-577e-5c26-a9e4-6d4368a3087a'::uuid, 'Pourquoi respire-t-on plus vite à l’effort ?', 'mcq', '["Pour apporter plus d’oxygène et évacuer le CO2","Parce qu’on a peur","Pour avoir plus chaud","Pour économiser de l’énergie"]'::jsonb, 0, 'Les muscles ont besoin d’oxygène et produisent du CO2 qu’il faut rejeter.', 4),
    ('ec0e5754-a785-5767-a739-9e977c4b818a'::uuid, '036e6709-577e-5c26-a9e4-6d4368a3087a'::uuid, 'Être essoufflé à l’effort est le signe d’un corps malade.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est normal : le corps s’adapte à l’effort, et on s’essouffle moins vite avec l’entraînement.', 5),
    ('44071cf1-0991-5677-8e54-4e2cf9dda6ba'::uuid, '036e6709-577e-5c26-a9e4-6d4368a3087a'::uuid, 'Que faire quand on a un point de côté ?', 'mcq', '["Boire beaucoup d’un coup","Ralentir et respirer profondément","Courir plus vite","Retenir son souffle"]'::jsonb, 1, 'Ralentir, souffler longuement et respirer profondément aide la douleur à passer.', 6),
    ('6894cf41-ae19-534c-a3ea-8b621a24f024'::uuid, '036e6709-577e-5c26-a9e4-6d4368a3087a'::uuid, 'On connaît parfaitement la cause du point de côté.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ses causes restent mal connues : le diaphragme et les ligaments qui tirent sur les organes sont les pistes principales.', 7),
    ('3b65a282-5581-5c14-a4e0-f7f2941532c3'::uuid, '036e6709-577e-5c26-a9e4-6d4368a3087a'::uuid, 'Comment éviter plus facilement le point de côté ?', 'mcq', '["Manger un gros repas avant","Ne jamais s’échauffer","Courir en retenant son souffle","Ne pas manger juste avant de courir"]'::jsonb, 3, 'Un estomac plein juste avant l’effort favorise le point de côté.', 8),
    ('71e679db-a743-5afe-9b28-d7f069675952'::uuid, '036e6709-577e-5c26-a9e4-6d4368a3087a'::uuid, 'Que devient le cœur d’un sportif d’endurance ?', 'mcq', '["Il s’arrête plus souvent","Il rétrécit","Il bat plus lentement au repos","Il bat plus vite au repos"]'::jsonb, 2, 'Le muscle cardiaque, renforcé, pompe plus à chaque battement : il bat moins souvent au repos.', 9),
    ('f23d1625-0153-50c4-9d56-13803707e705'::uuid, '036e6709-577e-5c26-a9e4-6d4368a3087a'::uuid, 'Comment compter son pouls au poignet ?', 'mcq', '["Compter les battements pendant 15 secondes puis multiplier par 4","Compter une seule seconde","Compter pendant 10 minutes","Appuyer fort sur le ventre"]'::jsonb, 0, '15 secondes × 4 donne le nombre de battements par minute.', 10),
    ('8cc2cae8-4abd-57d5-9e77-cbe129d32763'::uuid, '036e6709-577e-5c26-a9e4-6d4368a3087a'::uuid, 'Certains champions ont un pouls au repos d’environ 40 battements par minute.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la marque d’un « cœur d’athlète » : très entraîné, il bat lentement au repos.', 11),
    ('fd87180d-9d71-50ac-a07a-766f9464ecef'::uuid, '5a1d297b-5e90-5d78-8323-792e53ab0f47'::uuid, 'Qu’est-ce qu’une crampe ?', 'mcq', '["Une déchirure d’un os","Une brûlure de la peau","Une infection","Une contraction brutale et involontaire du muscle"]'::jsonb, 3, 'La crampe est une contraction du muscle, soudaine, douloureuse et que l’on ne contrôle pas.', 1),
    ('feafab05-8919-5c1a-af6c-ea8045df29b7'::uuid, '5a1d297b-5e90-5d78-8323-792e53ab0f47'::uuid, 'Que faire en cas de crampe ?', 'mcq', '["Appliquer de la glace sans arrêt","Étirer doucement le muscle, le masser, boire","Forcer d’un coup","Continuer à courir"]'::jsonb, 1, 'L’étirement doux relâche le muscle ; masser et boire aident aussi.', 2),
    ('dd50be43-79c0-5710-9a51-5122ec14e7b5'::uuid, '5a1d297b-5e90-5d78-8323-792e53ab0f47'::uuid, 'Quand apparaissent les courbatures après un effort inhabituel ?', 'mcq', '["Une semaine après","Jamais","24 à 48 heures plus tard","Immédiatement pendant l’effort"]'::jsonb, 2, 'Elles apparaissent un à deux jours après l’effort et durent 2 à 3 jours.', 3),
    ('2aed59b0-48c5-5b9f-9ed4-6aaea898384d'::uuid, '5a1d297b-5e90-5d78-8323-792e53ab0f47'::uuid, 'Les courbatures prouvent qu’on a bien progressé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles signalent des micro-lésions, pas un progrès : on progresse aussi sans courbature.', 4),
    ('a3d89f74-fe5c-59a5-ae5b-f457d177145e'::uuid, '5a1d297b-5e90-5d78-8323-792e53ab0f47'::uuid, 'Que provoque une ampoule ?', 'mcq', '["Un frottement répété sur la peau","Un coup de soleil","Un manque d’eau","Une crampe"]'::jsonb, 0, 'Le frottement décolle la peau, qui se remplit de liquide.', 5),
    ('e8ffe1a8-0292-5f07-a404-fcdc31a6456a'::uuid, '5a1d297b-5e90-5d78-8323-792e53ab0f47'::uuid, 'Faut-il percer systématiquement une ampoule ?', 'mcq', '["Oui, avec la main sale","Non, la peau protège la plaie","Oui, avec les doigts","Oui, avec un couteau"]'::jsonb, 1, 'Percer expose la plaie aux microbes : on ne le fait que si l’ampoule est grosse et gênante, avec du matériel désinfecté.', 6),
    ('c0800f45-2dff-5ed3-a3f3-3454e1aaedcd'::uuid, '5a1d297b-5e90-5d78-8323-792e53ab0f47'::uuid, 'Que veut dire GREC pour une entorse ?', 'mcq', '["Geste, Rapidité, Effort, Course","Gel, Rouler, Étirer, Courir","Gants, Rampe, Eau, Chaleur","Glace, Repos, Élévation, Compression"]'::jsonb, 3, 'Glace, repos, élévation et compression : le réflexe d’une entorse.', 7),
    ('b92106ad-83d1-5d0e-a55a-4021bc31f918'::uuid, '5a1d297b-5e90-5d78-8323-792e53ab0f47'::uuid, 'Dans quel cas faut-il aller voir un médecin ?', 'mcq', '["Pour une soif légère","Pour une chaussette mouillée","Quand on ne peut pas poser le pied","Pour une petite courbature"]'::jsonb, 2, 'Ne pas pouvoir poser le pied ou marcher indique une blessure sérieuse à faire examiner.', 8),
    ('6634feac-22e9-5f8c-a492-53a01377f897'::uuid, '5a1d297b-5e90-5d78-8323-792e53ab0f47'::uuid, 'Une douleur qui réveille la nuit est un signe qu’il faut consulter.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une douleur nocturne ou qui ne diminue pas mérite l’avis d’un médecin.', 9),
    ('f95412bc-e008-58dd-89aa-8dee3a28e2df'::uuid, '5a1d297b-5e90-5d78-8323-792e53ab0f47'::uuid, 'Que mettre dans son sac de sport ?', 'mcq', '["Une gourde, des pansements et des chaussettes de rechange","Seulement une console","Uniquement des boissons sucrées","Rien du tout"]'::jsonb, 0, 'Le petit kit de l’élève évite déshydratation et ampoules.', 10),
    ('021ea5f7-57db-546c-9969-da7d7ecae257'::uuid, '5a1d297b-5e90-5d78-8323-792e53ab0f47'::uuid, 'La glace sur une entorse se pose…', 'mcq', '["directement sur la peau","pendant toute la nuit","seulement le lendemain","enveloppée dans un linge"]'::jsonb, 3, 'La glace brûle la peau si on la pose directement : on l’enveloppe d’un linge.', 11),
    ('58489009-55a6-514a-9a0c-5c2b20b1187b'::uuid, '99e7f670-44fe-5adb-bc58-96016834aa1f'::uuid, 'Où ont lieu les premiers Jeux olympiques connus de l’Antiquité ?', 'mcq', '["À Athènes en 1896","À Olympie, en Grèce","À Rome","À Paris"]'::jsonb, 1, 'Les premiers Jeux connus se déroulent à Olympie en 776 av. J.-C.', 1),
    ('0071b4c0-6e40-5c83-851f-ff43d021d7ff'::uuid, '99e7f670-44fe-5adb-bc58-96016834aa1f'::uuid, 'En l’honneur de quel dieu avaient lieu les Jeux de l’Antiquité ?', 'mcq', '["Poséidon","Hercule","Zeus","Apollon"]'::jsonb, 2, 'Les Jeux d’Olympie honoraient Zeus, le roi des dieux.', 2),
    ('28f38c8a-97d0-502d-9027-8f446700fbe0'::uuid, '99e7f670-44fe-5adb-bc58-96016834aa1f'::uuid, 'Que recevait le vainqueur d’une épreuve dans l’Antiquité ?', 'mcq', '["Une couronne d’olivier","Une médaille d’or","Un bouclier en acier","Un sac de pièces"]'::jsonb, 0, 'Le vainqueur était couronné d’olivier.', 3),
    ('bbc81621-57a3-5e0f-a163-33c17e8a7c96'::uuid, '99e7f670-44fe-5adb-bc58-96016834aa1f'::uuid, 'Qui a relancé les Jeux olympiques modernes ?', 'mcq', '["Jules Verne","Pierre de Coubertin","Zeus","Napoléon"]'::jsonb, 1, 'Pierre de Coubertin a fait renaître les Jeux, dont la première édition moderne est celle d’Athènes en 1896.', 4),
    ('e431d580-3347-58ee-95e5-ae4243dedf08'::uuid, '99e7f670-44fe-5adb-bc58-96016834aa1f'::uuid, 'En quelle année a lieu la première édition des Jeux modernes ?', 'mcq', '["1900","1924","1948","1896"]'::jsonb, 3, 'En 1896, à Athènes, avec 14 nations et 241 athlètes.', 5),
    ('5289afdb-9a02-58d5-bdb6-e1b1226b0aec'::uuid, '99e7f670-44fe-5adb-bc58-96016834aa1f'::uuid, 'Les cinq anneaux olympiques représentent…', 'mcq', '["les cinq premiers sports","les cinq premiers vainqueurs","les cinq continents","les cinq sens"]'::jsonb, 2, 'Créés en 1913, ils symbolisent les cinq continents unis.', 6),
    ('13880634-e9a5-5f4e-beee-923816caa877'::uuid, '99e7f670-44fe-5adb-bc58-96016834aa1f'::uuid, 'Où ont eu lieu les premiers Jeux d’hiver, en 1924 ?', 'mcq', '["À Chamonix, en France","À Athènes","À Berlin","À Oslo"]'::jsonb, 0, 'Les premiers Jeux d’hiver se sont tenus à Chamonix en 1924.', 7),
    ('53e449b6-6c5b-57d5-97e5-a8cefcbc8b64'::uuid, '99e7f670-44fe-5adb-bc58-96016834aa1f'::uuid, 'Le mouvement paralympique est né à Stoke Mandeville, en Angleterre, en 1948.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Des athlètes en fauteuil roulant s’y sont affrontés ; les premiers Jeux paralympiques ont eu lieu à Rome en 1960.', 8),
    ('d79faadf-53ef-559b-8fc4-583a4f0e5790'::uuid, '99e7f670-44fe-5adb-bc58-96016834aa1f'::uuid, 'Paris 2024 a eu lieu du 26 juillet au 11 août 2024.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la date exacte des Jeux de Paris 2024.', 9),
    ('ba7507d6-43bc-5632-b6b4-b2425f3fa686'::uuid, '99e7f670-44fe-5adb-bc58-96016834aa1f'::uuid, 'Combien de titres olympiques Léon Marchand a-t-il gagnés à Paris 2024 ?', 'mcq', '["1","7","10","4"]'::jsonb, 3, 'Léon Marchand a remporté quatre titres olympiques.', 10),
    ('68d3973c-c1b4-5e03-9534-02c3039690f8'::uuid, '99e7f670-44fe-5adb-bc58-96016834aa1f'::uuid, 'Aux Jeux de 1896, des femmes participaient déjà aux épreuves.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'En 1896, seuls des hommes étaient engagés ; la parité n’a été atteinte qu’à Paris 2024.', 11),
    ('3b40c71d-14b7-5527-b579-396a910d9bb0'::uuid, '99e7f670-44fe-5adb-bc58-96016834aa1f'::uuid, 'Quelle place la France a-t-elle occupée au tableau des médailles de Paris 2024 ?', 'mcq', '["20e","5e","1re","10e"]'::jsonb, 1, 'La France a terminé 5e, avec 64 médailles dont 16 d’or.', 12),
    ('484203c9-942a-52c8-a189-ca65e7a367de'::uuid, '34c557e1-d1f9-527a-8eae-0d5fb18a00c7'::uuid, 'Quelle athlète française a gagné le 400 m aux Jeux de 1992 et de 1996 ?', 'mcq', '["Clarisse Agbegnenou","Pauline Ferrand-Prévot","Marie-José Pérec","Laure Manaudou"]'::jsonb, 2, 'Marie-José Pérec a remporté le 400 m à Barcelone et à Atlanta (où elle a aussi gagné le 200 m).', 1),
    ('03a35f41-0d9d-50b8-86b3-48ef1cba4134'::uuid, '34c557e1-d1f9-527a-8eae-0d5fb18a00c7'::uuid, 'Dans quelle discipline Teddy Riner est-il champion ?', 'mcq', '["Le judo","Le tennis","La natation","Le biathlon"]'::jsonb, 0, 'Teddy Riner est un judoka des plus de 100 kg.', 2),
    ('3dc0ba35-c9d4-5e39-b6d0-dc9000478bf9'::uuid, '34c557e1-d1f9-527a-8eae-0d5fb18a00c7'::uuid, 'Combien de titres olympiques individuels a remporté Léon Marchand à Paris 2024 ?', 'mcq', '["1","4","2","6"]'::jsonb, 1, 'Il a gagné le 200 m brasse, le 200 m papillon, le 200 m 4 nages et le 400 m 4 nages.', 3),
    ('93187fcd-6e6f-5d68-a9d0-e5f686aa43c0'::uuid, '34c557e1-d1f9-527a-8eae-0d5fb18a00c7'::uuid, 'Qui a marqué deux buts de la tête en finale de la Coupe du monde 1998 ?', 'mcq', '["Kylian Mbappé","Tony Parker","Teddy Riner","Zinédine Zidane"]'::jsonb, 3, 'Zidane a marqué deux buts de la tête contre le Brésil (3-0).', 4),
    ('0555e6fe-1331-5720-a30a-ffffcf3219ef'::uuid, '34c557e1-d1f9-527a-8eae-0d5fb18a00c7'::uuid, 'Quel est le score de la finale de la Coupe du monde 1998 entre la France et le Brésil ?', 'mcq', '["2-1","4-2","3-0","1-0"]'::jsonb, 2, 'La France a battu le Brésil 3-0 au Stade de France.', 5),
    ('0ab26a7f-ff9c-580d-a6f9-c2e2bef4ffb1'::uuid, '34c557e1-d1f9-527a-8eae-0d5fb18a00c7'::uuid, 'Kylian Mbappé est devenu champion du monde en 2018 à 19 ans.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il avait 19 ans et a marqué 4 buts dans la compétition.', 6),
    ('ecfe652f-5fe6-5e66-a3bc-971f77de8b85'::uuid, '34c557e1-d1f9-527a-8eae-0d5fb18a00c7'::uuid, 'Avec quelle équipe Tony Parker a-t-il gagné ses titres NBA ?', 'mcq', '["San Antonio","Boston","Chicago","Miami"]'::jsonb, 0, 'Tony Parker a gagné 4 titres NBA avec San Antonio (2003, 2005, 2007 et 2014).', 7),
    ('affba48f-743b-5cea-976a-7bc79458bb05'::uuid, '34c557e1-d1f9-527a-8eae-0d5fb18a00c7'::uuid, 'Dans quel sport Martin Fourcade a-t-il gagné ses titres olympiques ?', 'mcq', '["Le judo","La natation","L’athlétisme","Le biathlon"]'::jsonb, 3, 'Le biathlon combine ski de fond et tir à la carabine.', 8),
    ('c3f88361-5060-50b1-ae19-a2ef37c10011'::uuid, '34c557e1-d1f9-527a-8eae-0d5fb18a00c7'::uuid, 'Laure Manaudou a gagné le 400 m nage libre aux Jeux d’Athènes en 2004.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle avait 17 ans quand elle a remporté ce titre olympique.', 9),
    ('8d92c93b-fb3c-5087-9c5c-b171a9ed0a15'::uuid, '34c557e1-d1f9-527a-8eae-0d5fb18a00c7'::uuid, 'Combien d’épreuves de ski alpin Jean-Claude Killy a-t-il gagnées à Grenoble en 1968 ?', 'mcq', '["0","3","1","5"]'::jsonb, 1, 'Jean-Claude Killy a gagné les trois épreuves de ski alpin, devenant une légende nationale.', 10),
    ('48ef67db-0602-5618-8393-5bac0433b0e6'::uuid, '34c557e1-d1f9-527a-8eae-0d5fb18a00c7'::uuid, 'En quelle catégorie Clarisse Agbegnenou est-elle devenue championne olympique à Tokyo ?', 'mcq', '["−48 kg","−90 kg","−63 kg","+100 kg"]'::jsonb, 2, 'Clarisse Agbegnenou a été championne olympique des moins de 63 kg à Tokyo en 2021.', 11),
    ('5318293b-1f77-5db4-91f2-91136448bb3d'::uuid, 'a7dbe341-24c5-578a-a370-9bd038f11326'::uuid, 'Combien de joueurs une équipe de football aligne-t-elle sur le terrain, gardien compris ?', 'mcq', '["7","11","9","12"]'::jsonb, 1, 'Une équipe de football compte 11 joueurs, dont le gardien.', 1),
    ('7b407840-10a3-5609-9bb8-f3cef3e788f0'::uuid, 'a7dbe341-24c5-578a-a370-9bd038f11326'::uuid, 'Combien de remplacements une équipe peut-elle faire dans un match, depuis la règle permanente de 2022 ?', 'mcq', '["3","1","8","5"]'::jsonb, 3, 'Depuis 2022, la règle permanente autorise 5 remplacements par équipe.', 2),
    ('8bcd14cc-064f-5a3a-ab89-efedd80ea978'::uuid, 'a7dbe341-24c5-578a-a370-9bd038f11326'::uuid, 'Être en position de hors-jeu est toujours une faute sanctionnée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La position seule ne suffit pas : il faut aussi participer au jeu au moment de la passe pour être sanctionné.', 3),
    ('0a8275fe-8f13-5de4-bfac-15a4e73d7b91'::uuid, 'a7dbe341-24c5-578a-a370-9bd038f11326'::uuid, 'Par rapport à quoi est jugée la position de hors-jeu d’un attaquant ?', 'mcq', '["Le gardien seul","Le numéro du maillot","Le ballon et l’avant-dernier défenseur","Le milieu de terrain"]'::jsonb, 2, 'L’attaquant doit être plus près de la ligne de but que le ballon et que l’avant-dernier défenseur adverse.', 4),
    ('912042b1-706b-5095-89e3-17d799dbb9a1'::uuid, 'a7dbe341-24c5-578a-a370-9bd038f11326'::uuid, 'Dans quelle situation le hors-jeu est-il impossible ?', 'mcq', '["Sur une touche","Sur une passe longue dans la surface","Sur un tir cadré","Sur un centre venu de l’aile"]'::jsonb, 0, 'Il n’y a jamais de hors-jeu directement sur une touche, un corner ou un coup de pied de but.', 5),
    ('021a5a83-81aa-56bf-8d12-462799c98f3e'::uuid, 'a7dbe341-24c5-578a-a370-9bd038f11326'::uuid, 'À quelle distance du but se tire un penalty ?', 'mcq', '["6 mètres","16 mètres","9 mètres","11 mètres"]'::jsonb, 3, 'Le penalty se tire à 11 mètres, face au gardien seul.', 6),
    ('2d0cbcfc-0956-534a-8631-f32f9d765e03'::uuid, 'a7dbe341-24c5-578a-a370-9bd038f11326'::uuid, 'Un joueur reçoit deux cartons jaunes dans le même match. Que se passe-t-il ?', 'mcq', '["Le match est arrêté","Il est expulsé, comme avec un carton rouge","Il reçoit un simple avertissement de plus","Il sort et son équipe peut le remplacer"]'::jsonb, 1, 'Deux jaunes équivalent à un rouge : le joueur est expulsé et personne ne le remplace.', 7),
    ('a162e523-541a-5624-a27c-546942bd51af'::uuid, 'a7dbe341-24c5-578a-a370-9bd038f11326'::uuid, 'Un joueur est dans sa propre moitié de terrain quand on lui passe le ballon. Peut-il être hors-jeu ?', 'mcq', '["Oui, s’il est le plus avancé","Oui, si le gardien est sorti","Non, jamais dans sa moitié de terrain","Oui, si un défenseur est derrière lui"]'::jsonb, 2, 'Dans sa propre moitié de terrain, on ne peut pas être hors-jeu, quelle que soit la position des défenseurs.', 8),
    ('1f3f010c-f0ff-5de2-ac89-4149192ca357'::uuid, 'a7dbe341-24c5-578a-a370-9bd038f11326'::uuid, 'Le gardien adverse compte parmi les défenseurs pour juger un hors-jeu.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le gardien est un défenseur comme les autres : il peut être l’avant-dernier ou le dernier adversaire.', 9),
    ('699b2943-4ceb-5f75-9cfc-fdb4c97c2a6d'::uuid, 'a7dbe341-24c5-578a-a370-9bd038f11326'::uuid, 'La VAR a été utilisée pour la première fois à une Coupe du monde en…', 'mcq', '["2018","1998","2010","2022"]'::jsonb, 0, 'L’assistance vidéo à l’arbitrage a fait son entrée en Coupe du monde en 2018.', 10),
    ('f7ca5b74-e877-5210-a79b-a4bf46becbee'::uuid, 'a7dbe341-24c5-578a-a370-9bd038f11326'::uuid, 'La VAR remplace l’arbitre sur le terrain, qui n’a plus le dernier mot.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La VAR conseille l’arbitre sur certaines décisions importantes, mais c’est lui qui décide.', 11),
    ('163a78c0-b0eb-5afb-a992-43bacbe5aea1'::uuid, '3a2325b3-3d94-5afd-894f-e66b92822f3f'::uuid, 'À quelle hauteur se trouve le panier de basket ?', 'mcq', '["3,50 mètres","3,05 mètres","2,43 mètres","2,80 mètres"]'::jsonb, 1, 'Le panier est fixé à 3,05 mètres du sol, partout dans le monde.', 1),
    ('abb42547-4bf4-5281-a61f-19de0a7d7fa2'::uuid, '3a2325b3-3d94-5afd-894f-e66b92822f3f'::uuid, 'Combien de joueurs une équipe de basket aligne-t-elle sur le terrain ?', 'mcq', '["6","7","11","5"]'::jsonb, 3, 'Chaque équipe a 5 joueurs sur le terrain.', 2),
    ('5e177935-0de3-5f52-b7a5-0b46b85882d7'::uuid, '3a2325b3-3d94-5afd-894f-e66b92822f3f'::uuid, 'Combien vaut un lancer franc réussi ?', 'mcq', '["3 points","0 point","1 point","2 points"]'::jsonb, 2, 'Un lancer franc vaut 1 point, un tir normal 2 et un tir derrière la ligne 3.', 3),
    ('f85311f2-3f64-5ce2-babb-29ac3d339448'::uuid, '3a2325b3-3d94-5afd-894f-e66b92822f3f'::uuid, 'Que signifie « marcher » au basket ?', 'mcq', '["Faire plus de deux appuis avec le ballon sans dribbler","Marcher sans le ballon","Dribbler avec les deux mains","Sortir du terrain"]'::jsonb, 0, 'Tenir le ballon et avancer au-delà des deux appuis sans le faire rebondir est une violation : le ballon passe à l’adversaire.', 4),
    ('d750c7a1-b5c7-5c2e-8885-b98c6fec095d'::uuid, '3a2325b3-3d94-5afd-894f-e66b92822f3f'::uuid, 'Dans quel délai une équipe doit-elle tirer après avoir récupéré le ballon ?', 'mcq', '["8 secondes","3 secondes","60 secondes","24 secondes"]'::jsonb, 3, 'Les 24 secondes obligent l’équipe à tenter sa chance avant la fin du chronomètre.', 5),
    ('8c392dcb-effb-5912-89df-e5701aa9d243'::uuid, '3a2325b3-3d94-5afd-894f-e66b92822f3f'::uuid, 'Quelle règle impose de franchir la ligne médiane en 8 secondes ?', 'mcq', '["Le lancer franc","La règle des 8 secondes","La règle des 3 secondes","La reprise de dribble"]'::jsonb, 1, 'Après avoir récupéré le ballon dans son camp, on a 8 secondes pour passer la ligne médiane.', 6),
    ('ce87db2f-14f3-517d-8c26-a2163d38942b'::uuid, '3a2325b3-3d94-5afd-894f-e66b92822f3f'::uuid, 'Un match de la NBA dure 4 quarts-temps de 12 minutes, contre 10 minutes en FIBA.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La NBA joue 4 × 12 minutes, alors que les règles FIBA donnent 4 × 10 minutes.', 7),
    ('3f52e810-2364-54f3-ac86-c64ad9eb60d8'::uuid, '3a2325b3-3d94-5afd-894f-e66b92822f3f'::uuid, 'Après combien de fautes personnelles un joueur est-il exclu en règles FIBA ?', 'mcq', '["6","10","5","3"]'::jsonb, 2, 'En FIBA, la cinquième faute personnelle exclut le joueur (la sixième en NBA).', 8),
    ('60feb9b1-772d-5ca5-b25b-fbae4a011688'::uuid, '3a2325b3-3d94-5afd-894f-e66b92822f3f'::uuid, 'La ligne à trois points est exactement à la même distance en FIBA et en NBA.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est à 6,75 m en FIBA et à 7,24 m en NBA.', 9),
    ('28935d6e-9539-54e3-876d-94a6061fb26c'::uuid, '3a2325b3-3d94-5afd-894f-e66b92822f3f'::uuid, 'Un joueur arrête de dribbler, puis redémarre son dribble. Que se passe-t-il ?', 'mcq', '["C’est une reprise de dribble : le ballon passe à l’adversaire","C’est un panier de plus","C’est autorisé","C’est un lancer franc pour lui"]'::jsonb, 0, 'Une fois le dribble arrêté, on doit passer ou tirer ; redribbler est une faute de reprise de dribble.', 10),
    ('09c66ce9-ece9-556c-acd6-952be0a06a82'::uuid, '3a2325b3-3d94-5afd-894f-e66b92822f3f'::uuid, 'Un attaquant peut rester trois minutes dans la raquette sans problème.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La règle des 3 secondes l’interdit : au-delà, le ballon passe à l’adversaire.', 11),
    ('24419317-0b26-5af8-aa2a-fb658bb7bdc5'::uuid, '32b9d4d6-5654-5948-ae53-66bf12dbe350'::uuid, 'Combien de joueurs, gardien compris, une équipe de handball a-t-elle sur le terrain ?', 'mcq', '["5","7","6","11"]'::jsonb, 1, 'Une équipe de handball aligne 6 joueurs de champ et un gardien, soit 7.', 1),
    ('53f2a41d-65cd-562b-b9be-b5f66089943d'::uuid, '32b9d4d6-5654-5948-ae53-66bf12dbe350'::uuid, 'Combien de pas peut-on faire avec le ballon en main au handball ?', 'mcq', '["1","5","Autant qu’on veut","3"]'::jsonb, 3, 'On ne fait pas plus de trois pas avec le ballon sans dribbler.', 2),
    ('3b4462cd-9bf7-5301-8ea3-b225370621f2'::uuid, '32b9d4d6-5654-5948-ae53-66bf12dbe350'::uuid, 'Qui a le droit d’entrer dans la zone des 6 mètres au handball ?', 'mcq', '["Les attaquants","Les remplaçants","Seulement le gardien","Tous les joueurs"]'::jsonb, 2, 'La zone des 6 mètres est réservée au gardien de but.', 3),
    ('24688afd-b4f3-5902-99c8-3a419fd015d3'::uuid, '32b9d4d6-5654-5948-ae53-66bf12dbe350'::uuid, 'Que se passe-t-il quand un joueur de handball reçoit une exclusion de 2 minutes ?', 'mcq', '["Il sort 2 minutes et son équipe joue à six","Il est exclu du match pour toujours","Il reste mais perd un point","Son équipe joue à huit"]'::jsonb, 0, 'Pendant deux minutes, l’équipe reste en infériorité numérique.', 4),
    ('c2dd5925-1032-5001-96a1-081d7d2d109d'::uuid, '32b9d4d6-5654-5948-ae53-66bf12dbe350'::uuid, 'Le jeu passif est une règle qui oblige une équipe à…', 'mcq', '["défendre en zone","changer de gardien","marquer deux fois","tenter vraiment d’attaquer"]'::jsonb, 3, 'Si une équipe ne cherche pas à marquer, l’arbitre signale le jeu passif et elle doit tirer vite.', 5),
    ('c7ff9914-1b07-5575-9db0-1177717fa136'::uuid, '32b9d4d6-5654-5948-ae53-66bf12dbe350'::uuid, 'À partir de combien de points un set de volley est-il gagné, avec 2 points d’écart ?', 'mcq', '["30","25","15","21"]'::jsonb, 1, 'Un set se gagne à 25 points, avec au moins 2 points d’écart ; seul le 5e set va à 15.', 6),
    ('82a2fb31-a6d2-53ed-a7ae-5f460b08746c'::uuid, '32b9d4d6-5654-5948-ae53-66bf12dbe350'::uuid, 'Chaque équipe de volley peut toucher le ballon au maximum trois fois avant de le renvoyer.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La règle des trois touches maximum oblige à construire l’attaque.', 7),
    ('0df1cb26-de14-5801-8457-11b38a7fba67'::uuid, '32b9d4d6-5654-5948-ae53-66bf12dbe350'::uuid, 'Que peut faire le libéro, en maillot de couleur différente ?', 'mcq', '["Servir toujours","Arbitrer","Défendre seulement","Attaquer au filet"]'::jsonb, 2, 'Le libéro est spécialisé dans la défense : il ne peut ni attaquer ni servir.', 8),
    ('e0d9ff3e-bc3d-5347-8901-f6a09f719e34'::uuid, '32b9d4d6-5654-5948-ae53-66bf12dbe350'::uuid, 'À quelle hauteur est le filet de volley pour les hommes ?', 'mcq', '["2,43 m","2,24 m","3,05 m","1,80 m"]'::jsonb, 0, '2,43 m pour les hommes, 2,24 m pour les femmes.', 9),
    ('bb00a86d-26e4-588f-aaac-a50384973cf6'::uuid, '32b9d4d6-5654-5948-ae53-66bf12dbe350'::uuid, 'En volley, la rotation permet à tous les joueurs de servir.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'À chaque récupération du service, les joueurs tournent d’une place : tout le monde passe au service.', 10),
    ('438d078f-7dc2-5b07-9900-61f9da319718'::uuid, '32b9d4d6-5654-5948-ae53-66bf12dbe350'::uuid, 'En quelle année l’équipe de France masculine de handball a-t-elle remporté l’or olympique pour la première fois ?', 'mcq', '["2016","2008","1992","2000"]'::jsonb, 1, 'Les Experts ont gagné l’or olympique à Pékin en 2008, puis en 2012 et en 2020.', 11),
    ('44260d8d-c1c5-51cc-8194-dabbea770615'::uuid, 'a9af0f94-b750-5a4f-a077-83b8ed74441d'::uuid, 'Combien de joueurs compte une équipe de rugby à XV ?', 'mcq', '["7","11","13","15"]'::jsonb, 3, 'XV, c’est 15 en chiffres romains : 15 joueurs par équipe.', 1),
    ('8147a5be-1794-5c16-88bb-a6644e270c63'::uuid, 'a9af0f94-b750-5a4f-a077-83b8ed74441d'::uuid, 'Combien de temps dure chaque mi-temps au rugby à XV ?', 'mcq', '["30 minutes","7 minutes","40 minutes","45 minutes"]'::jsonb, 2, 'Un match de rugby à XV se joue en deux mi-temps de 40 minutes.', 2),
    ('5c2ef879-107a-5af8-a4cd-1552b3a949d1'::uuid, 'a9af0f94-b750-5a4f-a077-83b8ed74441d'::uuid, 'Dans quelle direction peut-on passer le ballon au rugby ?', 'mcq', '["Vers l’arrière ou sur le côté","Vers l’avant seulement","Dans toutes les directions","Vers le haut seulement"]'::jsonb, 0, 'La passe vers l’avant est un en-avant : on passe en arrière ou latéralement.', 3),
    ('41b51ebb-ab1f-557d-b9df-ea7a65e24374'::uuid, 'a9af0f94-b750-5a4f-a077-83b8ed74441d'::uuid, 'Que vaut un essai au rugby à XV ?', 'mcq', '["3 points","2 points","7 points","5 points"]'::jsonb, 3, 'L’essai vaut 5 points ; la transformation en ajoute 2.', 4),
    ('62b5eb3a-0781-5b62-9d7b-8e0d38ee3989'::uuid, 'a9af0f94-b750-5a4f-a077-83b8ed74441d'::uuid, 'Que se passe-t-il après un en-avant ?', 'mcq', '["Une touche pour la même équipe","Une mêlée pour l’équipe adverse","Un essai de pénalité","Un carton rouge"]'::jsonb, 1, 'L’en-avant se sanctionne par une mêlée au profit des adversaires.', 5),
    ('0da9c302-d5f1-5e9e-b65e-de13d298e790'::uuid, 'a9af0f94-b750-5a4f-a077-83b8ed74441d'::uuid, 'Où le plaquage doit-il se faire ?', 'mcq', '["À la tête","Peu importe où","Sous la ligne des épaules","Au niveau du cou"]'::jsonb, 2, 'Plaquer au cou ou à la tête est interdit : on plaque sous la ligne des épaules.', 6),
    ('fef1ee9e-5932-571f-aaf6-61af1e19b00b'::uuid, 'a9af0f94-b750-5a4f-a077-83b8ed74441d'::uuid, 'Une pénalité réussie entre les poteaux rapporte 3 points.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La pénalité comme le drop valent 3 points.', 7),
    ('83b20584-e085-5c42-999d-c46b41d8dda9'::uuid, 'a9af0f94-b750-5a4f-a077-83b8ed74441d'::uuid, 'Que fait-on pendant une touche ?', 'mcq', '["On lance le ballon entre deux lignes de joueurs","On tire un penalty","On forme une mêlée","On change de camp"]'::jsonb, 0, 'Un coéquipier lance le ballon entre les deux lignes, et les joueurs sautent pour l’attraper.', 8),
    ('a9dccf36-16de-5d2f-a0f2-0ced2f8f9eff'::uuid, 'a9af0f94-b750-5a4f-a077-83b8ed74441d'::uuid, 'Au rugby, qui peut discuter avec l’arbitre ?', 'mcq', '["Le public du stade","Le capitaine, avec respect","Tous les joueurs à voix haute","Les supporters"]'::jsonb, 1, 'On appelle l’arbitre « Monsieur » et seul le capitaine lui parle.', 9),
    ('68a5042c-1a0b-5023-9ed0-5475dbde22c2'::uuid, 'a9af0f94-b750-5a4f-a077-83b8ed74441d'::uuid, 'Le rugby à 7 oppose deux équipes de 7 joueurs sur des matchs de 2 × 7 minutes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la version courte et rapide du rugby, qui a donné l’or à la France à Paris 2024.', 10),
    ('a2b73f76-0b6f-5d15-8413-73dad7c03864'::uuid, 'a9af0f94-b750-5a4f-a077-83b8ed74441d'::uuid, 'Un joueur lance le ballon vers l’avant à son coéquipier. L’arbitre siffle…', 'mcq', '["un essai","une transformation","un drop","un en-avant"]'::jsonb, 3, 'Toute passe vers l’avant est un en-avant, quelle que soit la distance.', 11),
    ('8232a901-64b5-55b7-bcd4-b9cbf3930a9e'::uuid, 'a9af0f94-b750-5a4f-a077-83b8ed74441d'::uuid, 'Le ruck est un rassemblement de joueurs autour d’un ballon posé au sol.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Après un plaquage, des joueurs se lient debout au-dessus du ballon au sol pour le protéger ou le récupérer.', 12),
    ('bd719d2d-6d1a-59fa-ac6e-345fa6421e1c'::uuid, '63fc97e2-da6c-51b6-a345-72c0ecd91f37'::uuid, 'Quels sont les points d’un jeu au tennis ?', 'mcq', '["10, 20, 30","5, 10, 15","15, 30, 40","1, 2, 3"]'::jsonb, 2, 'Les points d’un jeu se comptent 15, 30 et 40, puis le jeu.', 1),
    ('802cb849-19ef-5cf6-83aa-43e421879e82'::uuid, '63fc97e2-da6c-51b6-a345-72c0ecd91f37'::uuid, 'Que se passe-t-il quand le score d’un jeu est de 40 partout ?', 'mcq', '["C’est l’égalité : il faut deux points d’écart","Le jeu est rejoué","Le premier serveur gagne","Le set se termine"]'::jsonb, 0, 'À l’égalité, un joueur doit gagner deux points de suite (avantage puis jeu).', 2),
    ('802d283b-df09-5384-9217-a961355d1ed4'::uuid, '63fc97e2-da6c-51b6-a345-72c0ecd91f37'::uuid, 'Combien de jeux faut-il gagner pour un set, avec 2 jeux d’écart ?', 'mcq', '["4","10","3","6"]'::jsonb, 3, 'On gagne un set à 6 jeux, avec 2 jeux d’écart.', 3),
    ('5b3be70e-8f2a-5b1a-9fe2-8a2b6554e332'::uuid, '63fc97e2-da6c-51b6-a345-72c0ecd91f37'::uuid, 'Quand joue-t-on un tie-break ?', 'mcq', '["Au premier set","À 6 jeux partout","À 40 partout","À 3 sets partout"]'::jsonb, 1, 'À 6-6 dans un set, on joue un tie-break pour décider du gagnant du set.', 4),
    ('3182883a-4eb6-56a6-94ce-20baf74e37ca'::uuid, '63fc97e2-da6c-51b6-a345-72c0ecd91f37'::uuid, 'Combien de points faut-il pour gagner un tie-break ?', 'mcq', '["10","3","7, avec 2 points d’écart","5"]'::jsonb, 2, 'Le tie-break se gagne à 7 points avec 2 points d’écart.', 5),
    ('f4e4cb4f-53a1-52b1-9e38-b241c06862f5'::uuid, '63fc97e2-da6c-51b6-a345-72c0ecd91f37'::uuid, 'Combien de balles de service a-t-on pour chaque point ?', 'mcq', '["Deux","Une","Trois","Quatre"]'::jsonb, 0, 'Après une première faute, on a une seconde balle ; deux fautes font une double faute.', 6),
    ('46234a60-b82f-5a95-8f39-c03e976bb6ca'::uuid, '63fc97e2-da6c-51b6-a345-72c0ecd91f37'::uuid, 'Un « let » au service signifie…', 'mcq', '["que la balle est trop haute","qu’on rejoue le service","que le point est perdu","que le jeu est gagné"]'::jsonb, 1, 'Quand le service touche le filet et tombe dans le bon carré, le service est rejoué.', 7),
    ('826fd2a9-c4b1-5868-a43e-169026cf56c5'::uuid, '63fc97e2-da6c-51b6-a345-72c0ecd91f37'::uuid, 'Roland-Garros se joue sur terre battue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le tournoi de Roland-Garros se dispute sur terre battue, à Paris.', 8),
    ('40e0bced-0b27-55ca-afc1-ade6f5729400'::uuid, '63fc97e2-da6c-51b6-a345-72c0ecd91f37'::uuid, 'Combien de fois Rafael Nadal a-t-il gagné Roland-Garros ?', 'mcq', '["7","10","20","14"]'::jsonb, 3, 'Rafael Nadal détient le record de 14 victoires à Roland-Garros.', 9),
    ('9102f3f2-a221-56c3-a288-5945e0610f37'::uuid, '63fc97e2-da6c-51b6-a345-72c0ecd91f37'::uuid, 'Au badminton, un set se joue en 21 points avec 2 points d’écart.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le set se joue à 21 points avec 2 d’écart, plafonné à 30.', 10),
    ('39314057-10f5-594c-b614-c500bbbc33f7'::uuid, '63fc97e2-da6c-51b6-a345-72c0ecd91f37'::uuid, 'Combien de sets faut-il gagner pour remporter un match de badminton ?', 'mcq', '["1","5","2","3"]'::jsonb, 2, 'Un match de badminton se joue au meilleur des trois sets : il faut en gagner 2.', 11),
    ('ffdd3680-a9eb-53e9-a94f-274addd02bc2'::uuid, '3203d366-11d3-5859-8539-a7da3709c457'::uuid, 'Quelle part de l’énergie dépensée par un muscle part en chaleur ?', 'mcq', '["Environ les trois quarts","Environ un dixième","Environ la moitié exactement","Presque rien"]'::jsonb, 0, 'Environ les trois quarts de l’énergie partent en chaleur et un quart seulement en mouvement.', 1),
    ('224518dc-233d-52e4-930d-b75679d715ff'::uuid, '3203d366-11d3-5859-8539-a7da3709c457'::uuid, 'Autour de quelle température le corps cherche-t-il à rester ?', 'mcq', '["30 °C","42 °C","25 °C","37 °C"]'::jsonb, 3, 'Le corps tient autour de 37 °C : c’est la température où les organes fonctionnent bien.', 2),
    ('0726c02c-d497-5b5a-ae87-b6cbdba16b67'::uuid, '3203d366-11d3-5859-8539-a7da3709c457'::uuid, 'Qu’est-ce qui refroidit réellement le corps quand on transpire ?', 'mcq', '["La couleur de la peau","L’évaporation de la sueur","La quantité de sueur","Le sel dans la sueur"]'::jsonb, 1, 'L’eau qui s’évapore prend de la chaleur à la peau : c’est l’évaporation qui refroidit.', 3),
    ('f698c717-fe32-58bf-980d-3999e51e044e'::uuid, '3203d366-11d3-5859-8539-a7da3709c457'::uuid, 'Pourquoi rougit-on pendant un effort ?', 'mcq', '["Le sang devient plus rouge","La peau est abîmée","Les vaisseaux de la peau se dilatent pour évacuer la chaleur","Le cœur s’arrête un instant"]'::jsonb, 2, 'Les vaisseaux sous la peau s’élargissent : plus de sang arrive près de la surface et la chaleur s’échappe.', 4),
    ('2d049d1c-ca14-5dac-9424-f7a2e200108f'::uuid, '3203d366-11d3-5859-8539-a7da3709c457'::uuid, 'Quand faut-il boire pendant un effort ?', 'mcq', '["Avant d’avoir soif","Seulement quand on a soif","Jamais pendant l’effort","Après l’effort uniquement"]'::jsonb, 0, 'La soif arrive quand le manque d’eau a déjà commencé : on boit avant, par petites gorgées.', 5),
    ('2fa1ed7c-be9c-5f2b-a002-a865a57d4fa7'::uuid, '3203d366-11d3-5859-8539-a7da3709c457'::uuid, 'La sueur qui coule sans s’évaporer refroidit autant que celle qui s’évapore.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seule l’évaporation prend la chaleur de la peau ; une sueur qui coule ne refroidit presque pas.', 6),
    ('3c0610b1-7f9f-564f-ad2e-ba308eb28397'::uuid, '3203d366-11d3-5859-8539-a7da3709c457'::uuid, 'Pourquoi transpire-t-on davantage quand l’air est humide sans vent ?', 'mcq', '["Le soleil chauffe plus","La sueur s’évapore mal, alors le corps en produit plus","L’eau est plus chaude","On a moins de glandes"]'::jsonb, 1, 'L’air humide ralentit l’évaporation : le corps transpire plus pour compenser et se refroidit moins bien.', 7),
    ('e2f00e91-6698-534f-9588-22a3fe7fe557'::uuid, '3203d366-11d3-5859-8539-a7da3709c457'::uuid, 'Combien de glandes sudoripares a-t-on environ sur la peau ?', 'mcq', '["20 à 40","200 à 400","2 à 4 milliards","2 à 4 millions"]'::jsonb, 3, 'On compte entre 2 et 4 millions de glandes qui fabriquent la sueur.', 8),
    ('50dbaae6-514f-544a-86a1-22c33f3c2fd5'::uuid, '3203d366-11d3-5859-8539-a7da3709c457'::uuid, 'Un élève a la peau très rouge et chaude, un mal de tête et des vertiges par forte chaleur. Que faire ?', 'mcq', '["Boire un grand verre d’eau glacée d’un coup","Mettre un pull pour transpirer plus","Arrêter l’effort, se mettre à l’ombre, se refroidir et prévenir un adulte","Continuer pour s’habituer"]'::jsonb, 2, 'Ce sont les signes d’un coup de chaleur : il faut stopper, refroidir le corps et faire appeler les secours si ça ne passe pas.', 9),
    ('9a23c78a-632a-58eb-b00c-41730c367258'::uuid, '3203d366-11d3-5859-8539-a7da3709c457'::uuid, 'On peut perdre 1 à 2 litres de sueur par heure lors d’un effort intense.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'À effort intense, la perte atteint un à deux litres par heure : d’où l’importance de s’hydrater.', 10),
    ('85d350fc-aae8-5921-bb60-35a51b385abc'::uuid, '3203d366-11d3-5859-8539-a7da3709c457'::uuid, 'Pourquoi s’habiller en couches est-il pratique pour le sport ?', 'mcq', '["On peut en enlever une quand on a chaud","Cela fait plus joli","On transpire moins","On court plus vite"]'::jsonb, 0, 'Les couches s’ajoutent ou s’enlèvent selon la température du corps, sans surchauffer ni se refroidir.', 11),
    ('3b64af55-cb81-5355-a532-7c391a4c153a'::uuid, '943d8780-a0ff-55f2-aaed-810a0456a28a'::uuid, 'Quelle est la fréquence cardiaque d’un adulte au repos ?', 'mcq', '["10 à 20 battements par minute","150 à 180 battements par minute","300 battements par minute","60 à 80 battements par minute"]'::jsonb, 3, 'Au repos, le cœur d’un adulte bat 60 à 80 fois par minute.', 1),
    ('bf0074d6-462b-5f0e-b423-fe6689a8e62f'::uuid, '943d8780-a0ff-55f2-aaed-810a0456a28a'::uuid, 'Combien de litres de sang le cœur envoie-t-il par minute à l’effort ?', 'mcq', '["200 litres","20 à 25 litres","1 litre","5 litres"]'::jsonb, 1, 'Au repos il envoie environ 5 litres par minute, et jusqu’à 20 à 25 à l’effort.', 2),
    ('57c7203e-75ca-5df7-b733-b7548a22c203'::uuid, '943d8780-a0ff-55f2-aaed-810a0456a28a'::uuid, 'Comment estime-t-on la fréquence cardiaque maximale ?', 'mcq', '["L’âge multiplié par 10","60 moins l’âge","220 moins l’âge","100 plus l’âge"]'::jsonb, 2, 'La formule 220 − âge donne une approximation, pas une mesure exacte.', 3),
    ('4a5a3613-aa3f-5e5f-a111-c52c6d9f0f3a'::uuid, '943d8780-a0ff-55f2-aaed-810a0456a28a'::uuid, 'Pourquoi respire-t-on plus vite à l’effort ?', 'mcq', '["Pour apporter plus d’oxygène et évacuer le CO2","Parce qu’on a peur","Pour avoir plus chaud","Pour économiser de l’énergie"]'::jsonb, 0, 'Les muscles ont besoin d’oxygène et produisent du CO2 qu’il faut rejeter.', 4),
    ('b5bbf4e8-97a7-5599-871c-3515f99b9a23'::uuid, '943d8780-a0ff-55f2-aaed-810a0456a28a'::uuid, 'Être essoufflé à l’effort est le signe d’un corps malade.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est normal : le corps s’adapte à l’effort, et on s’essouffle moins vite avec l’entraînement.', 5),
    ('29986870-ff95-53af-8e87-2fc399f66830'::uuid, '943d8780-a0ff-55f2-aaed-810a0456a28a'::uuid, 'Que faire quand on a un point de côté ?', 'mcq', '["Boire beaucoup d’un coup","Ralentir et respirer profondément","Courir plus vite","Retenir son souffle"]'::jsonb, 1, 'Ralentir, souffler longuement et respirer profondément aide la douleur à passer.', 6),
    ('68ec8eb0-1bf6-5db9-bdaa-6ab863a3de76'::uuid, '943d8780-a0ff-55f2-aaed-810a0456a28a'::uuid, 'On connaît parfaitement la cause du point de côté.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ses causes restent mal connues : le diaphragme et les ligaments qui tirent sur les organes sont les pistes principales.', 7),
    ('f10ca1a2-3dc9-56df-9ccb-c9ba5fd692c2'::uuid, '943d8780-a0ff-55f2-aaed-810a0456a28a'::uuid, 'Comment éviter plus facilement le point de côté ?', 'mcq', '["Manger un gros repas avant","Ne jamais s’échauffer","Courir en retenant son souffle","Ne pas manger juste avant de courir"]'::jsonb, 3, 'Un estomac plein juste avant l’effort favorise le point de côté.', 8),
    ('9ee162dd-a1bc-54a8-888f-feb09cea68d8'::uuid, '943d8780-a0ff-55f2-aaed-810a0456a28a'::uuid, 'Que devient le cœur d’un sportif d’endurance ?', 'mcq', '["Il s’arrête plus souvent","Il rétrécit","Il bat plus lentement au repos","Il bat plus vite au repos"]'::jsonb, 2, 'Le muscle cardiaque, renforcé, pompe plus à chaque battement : il bat moins souvent au repos.', 9),
    ('3714ac7f-b728-5e6a-b39f-c70e43c5fc5c'::uuid, '943d8780-a0ff-55f2-aaed-810a0456a28a'::uuid, 'Comment compter son pouls au poignet ?', 'mcq', '["Compter les battements pendant 15 secondes puis multiplier par 4","Compter une seule seconde","Compter pendant 10 minutes","Appuyer fort sur le ventre"]'::jsonb, 0, '15 secondes × 4 donne le nombre de battements par minute.', 10),
    ('67f0005e-77d5-56bc-ad2d-03a772a44b56'::uuid, '943d8780-a0ff-55f2-aaed-810a0456a28a'::uuid, 'Certains champions ont un pouls au repos d’environ 40 battements par minute.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la marque d’un « cœur d’athlète » : très entraîné, il bat lentement au repos.', 11),
    ('b602ca7d-6b88-5f3c-a14d-cf651a3ab189'::uuid, 'dc685b05-0826-53fd-b5d8-6532dbb2a533'::uuid, 'Qu’est-ce qu’une crampe ?', 'mcq', '["Une déchirure d’un os","Une brûlure de la peau","Une infection","Une contraction brutale et involontaire du muscle"]'::jsonb, 3, 'La crampe est une contraction du muscle, soudaine, douloureuse et que l’on ne contrôle pas.', 1),
    ('6eaa8688-ebc7-5f47-bd73-3706cea70806'::uuid, 'dc685b05-0826-53fd-b5d8-6532dbb2a533'::uuid, 'Que faire en cas de crampe ?', 'mcq', '["Appliquer de la glace sans arrêt","Étirer doucement le muscle, le masser, boire","Forcer d’un coup","Continuer à courir"]'::jsonb, 1, 'L’étirement doux relâche le muscle ; masser et boire aident aussi.', 2),
    ('80ee579d-7b3b-5688-ab40-e23f2625ae69'::uuid, 'dc685b05-0826-53fd-b5d8-6532dbb2a533'::uuid, 'Quand apparaissent les courbatures après un effort inhabituel ?', 'mcq', '["Une semaine après","Jamais","24 à 48 heures plus tard","Immédiatement pendant l’effort"]'::jsonb, 2, 'Elles apparaissent un à deux jours après l’effort et durent 2 à 3 jours.', 3),
    ('d221003b-de82-59bd-9148-2607f0ea7765'::uuid, 'dc685b05-0826-53fd-b5d8-6532dbb2a533'::uuid, 'Les courbatures prouvent qu’on a bien progressé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles signalent des micro-lésions, pas un progrès : on progresse aussi sans courbature.', 4),
    ('54192f3b-006f-5d09-9944-de114ee179af'::uuid, 'dc685b05-0826-53fd-b5d8-6532dbb2a533'::uuid, 'Que provoque une ampoule ?', 'mcq', '["Un frottement répété sur la peau","Un coup de soleil","Un manque d’eau","Une crampe"]'::jsonb, 0, 'Le frottement décolle la peau, qui se remplit de liquide.', 5),
    ('542d799b-ce77-5c2d-afae-c76a6a3b00b7'::uuid, 'dc685b05-0826-53fd-b5d8-6532dbb2a533'::uuid, 'Faut-il percer systématiquement une ampoule ?', 'mcq', '["Oui, avec la main sale","Non, la peau protège la plaie","Oui, avec les doigts","Oui, avec un couteau"]'::jsonb, 1, 'Percer expose la plaie aux microbes : on ne le fait que si l’ampoule est grosse et gênante, avec du matériel désinfecté.', 6),
    ('6fdc5f8b-c3e4-5eb7-8544-3de946c31c89'::uuid, 'dc685b05-0826-53fd-b5d8-6532dbb2a533'::uuid, 'Que veut dire GREC pour une entorse ?', 'mcq', '["Geste, Rapidité, Effort, Course","Gel, Rouler, Étirer, Courir","Gants, Rampe, Eau, Chaleur","Glace, Repos, Élévation, Compression"]'::jsonb, 3, 'Glace, repos, élévation et compression : le réflexe d’une entorse.', 7),
    ('9ab829ed-b475-58d4-a12e-277bf7bb0afb'::uuid, 'dc685b05-0826-53fd-b5d8-6532dbb2a533'::uuid, 'Dans quel cas faut-il aller voir un médecin ?', 'mcq', '["Pour une soif légère","Pour une chaussette mouillée","Quand on ne peut pas poser le pied","Pour une petite courbature"]'::jsonb, 2, 'Ne pas pouvoir poser le pied ou marcher indique une blessure sérieuse à faire examiner.', 8),
    ('7ca2c306-cf12-5e3b-b20e-d512dabd1990'::uuid, 'dc685b05-0826-53fd-b5d8-6532dbb2a533'::uuid, 'Une douleur qui réveille la nuit est un signe qu’il faut consulter.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une douleur nocturne ou qui ne diminue pas mérite l’avis d’un médecin.', 9),
    ('b052f2d6-43ab-5db1-a03b-8d5a5487d41e'::uuid, 'dc685b05-0826-53fd-b5d8-6532dbb2a533'::uuid, 'Que mettre dans son sac de sport ?', 'mcq', '["Une gourde, des pansements et des chaussettes de rechange","Seulement une console","Uniquement des boissons sucrées","Rien du tout"]'::jsonb, 0, 'Le petit kit de l’élève évite déshydratation et ampoules.', 10),
    ('b1a0b77a-72bd-57ed-8a61-2d9a3b049ad0'::uuid, 'dc685b05-0826-53fd-b5d8-6532dbb2a533'::uuid, 'La glace sur une entorse se pose…', 'mcq', '["directement sur la peau","pendant toute la nuit","seulement le lendemain","enveloppée dans un linge"]'::jsonb, 3, 'La glace brûle la peau si on la pose directement : on l’enveloppe d’un linge.', 11),
    ('a1e0532f-6cb8-5176-8a44-682aaa1a5805'::uuid, '12b7b848-b349-573a-ac92-f0d93c5f7f68'::uuid, 'Où ont lieu les premiers Jeux olympiques connus de l’Antiquité ?', 'mcq', '["À Athènes en 1896","À Olympie, en Grèce","À Rome","À Paris"]'::jsonb, 1, 'Les premiers Jeux connus se déroulent à Olympie en 776 av. J.-C.', 1),
    ('8dbde5e3-8915-57f7-b279-8fee19882c2e'::uuid, '12b7b848-b349-573a-ac92-f0d93c5f7f68'::uuid, 'En l’honneur de quel dieu avaient lieu les Jeux de l’Antiquité ?', 'mcq', '["Poséidon","Hercule","Zeus","Apollon"]'::jsonb, 2, 'Les Jeux d’Olympie honoraient Zeus, le roi des dieux.', 2),
    ('4181f7c5-8302-51ee-aeb1-bbc3def5e3db'::uuid, '12b7b848-b349-573a-ac92-f0d93c5f7f68'::uuid, 'Que recevait le vainqueur d’une épreuve dans l’Antiquité ?', 'mcq', '["Une couronne d’olivier","Une médaille d’or","Un bouclier en acier","Un sac de pièces"]'::jsonb, 0, 'Le vainqueur était couronné d’olivier.', 3),
    ('4d012f55-1336-5d7e-9edf-211899eb92f1'::uuid, '12b7b848-b349-573a-ac92-f0d93c5f7f68'::uuid, 'Qui a relancé les Jeux olympiques modernes ?', 'mcq', '["Jules Verne","Pierre de Coubertin","Zeus","Napoléon"]'::jsonb, 1, 'Pierre de Coubertin a fait renaître les Jeux, dont la première édition moderne est celle d’Athènes en 1896.', 4),
    ('6b634826-bb29-53a8-ad17-75839ee3ab37'::uuid, '12b7b848-b349-573a-ac92-f0d93c5f7f68'::uuid, 'En quelle année a lieu la première édition des Jeux modernes ?', 'mcq', '["1900","1924","1948","1896"]'::jsonb, 3, 'En 1896, à Athènes, avec 14 nations et 241 athlètes.', 5),
    ('d22b412e-041f-582d-a4b7-da92e9abe42d'::uuid, '12b7b848-b349-573a-ac92-f0d93c5f7f68'::uuid, 'Les cinq anneaux olympiques représentent…', 'mcq', '["les cinq premiers sports","les cinq premiers vainqueurs","les cinq continents","les cinq sens"]'::jsonb, 2, 'Créés en 1913, ils symbolisent les cinq continents unis.', 6),
    ('192d0eaf-e8b4-59dd-9eff-2c8789be5c16'::uuid, '12b7b848-b349-573a-ac92-f0d93c5f7f68'::uuid, 'Où ont eu lieu les premiers Jeux d’hiver, en 1924 ?', 'mcq', '["À Chamonix, en France","À Athènes","À Berlin","À Oslo"]'::jsonb, 0, 'Les premiers Jeux d’hiver se sont tenus à Chamonix en 1924.', 7),
    ('0f15f581-02c2-5e41-9e84-c4383d48cdfc'::uuid, '12b7b848-b349-573a-ac92-f0d93c5f7f68'::uuid, 'Le mouvement paralympique est né à Stoke Mandeville, en Angleterre, en 1948.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Des athlètes en fauteuil roulant s’y sont affrontés ; les premiers Jeux paralympiques ont eu lieu à Rome en 1960.', 8),
    ('b4355d81-d09e-5872-9011-aa8572a3b740'::uuid, '12b7b848-b349-573a-ac92-f0d93c5f7f68'::uuid, 'Paris 2024 a eu lieu du 26 juillet au 11 août 2024.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la date exacte des Jeux de Paris 2024.', 9),
    ('e915ce62-17f1-5ee8-b8a5-feee3fe51a47'::uuid, '12b7b848-b349-573a-ac92-f0d93c5f7f68'::uuid, 'Combien de titres olympiques Léon Marchand a-t-il gagnés à Paris 2024 ?', 'mcq', '["1","7","10","4"]'::jsonb, 3, 'Léon Marchand a remporté quatre titres olympiques.', 10),
    ('9436f04b-0ca0-5974-915c-82a9a5156814'::uuid, '12b7b848-b349-573a-ac92-f0d93c5f7f68'::uuid, 'Aux Jeux de 1896, des femmes participaient déjà aux épreuves.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'En 1896, seuls des hommes étaient engagés ; la parité n’a été atteinte qu’à Paris 2024.', 11),
    ('d3b03b1f-93e1-5137-8aba-cffd6303316d'::uuid, '12b7b848-b349-573a-ac92-f0d93c5f7f68'::uuid, 'Quelle place la France a-t-elle occupée au tableau des médailles de Paris 2024 ?', 'mcq', '["20e","5e","1re","10e"]'::jsonb, 1, 'La France a terminé 5e, avec 64 médailles dont 16 d’or.', 12),
    ('02f4ffcc-0fc3-5d72-8f5a-068b55b4a84f'::uuid, 'a8366eb7-9a1e-5d4e-9368-985771e24cae'::uuid, 'Quelle athlète française a gagné le 400 m aux Jeux de 1992 et de 1996 ?', 'mcq', '["Clarisse Agbegnenou","Pauline Ferrand-Prévot","Marie-José Pérec","Laure Manaudou"]'::jsonb, 2, 'Marie-José Pérec a remporté le 400 m à Barcelone et à Atlanta (où elle a aussi gagné le 200 m).', 1),
    ('c99e355e-6390-5f30-99d9-849a77fbdf35'::uuid, 'a8366eb7-9a1e-5d4e-9368-985771e24cae'::uuid, 'Dans quelle discipline Teddy Riner est-il champion ?', 'mcq', '["Le judo","Le tennis","La natation","Le biathlon"]'::jsonb, 0, 'Teddy Riner est un judoka des plus de 100 kg.', 2),
    ('01fe1882-2d0f-5888-aa30-e83b5e11b6c3'::uuid, 'a8366eb7-9a1e-5d4e-9368-985771e24cae'::uuid, 'Combien de titres olympiques individuels a remporté Léon Marchand à Paris 2024 ?', 'mcq', '["1","4","2","6"]'::jsonb, 1, 'Il a gagné le 200 m brasse, le 200 m papillon, le 200 m 4 nages et le 400 m 4 nages.', 3),
    ('12bbff61-f674-5b92-8c41-e81bff7b88d1'::uuid, 'a8366eb7-9a1e-5d4e-9368-985771e24cae'::uuid, 'Qui a marqué deux buts de la tête en finale de la Coupe du monde 1998 ?', 'mcq', '["Kylian Mbappé","Tony Parker","Teddy Riner","Zinédine Zidane"]'::jsonb, 3, 'Zidane a marqué deux buts de la tête contre le Brésil (3-0).', 4),
    ('904b6e32-041a-5af9-b6dc-41c09dd7dea0'::uuid, 'a8366eb7-9a1e-5d4e-9368-985771e24cae'::uuid, 'Quel est le score de la finale de la Coupe du monde 1998 entre la France et le Brésil ?', 'mcq', '["2-1","4-2","3-0","1-0"]'::jsonb, 2, 'La France a battu le Brésil 3-0 au Stade de France.', 5),
    ('b92f485a-a5f4-526d-b6d3-0a6806ce02e6'::uuid, 'a8366eb7-9a1e-5d4e-9368-985771e24cae'::uuid, 'Kylian Mbappé est devenu champion du monde en 2018 à 19 ans.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il avait 19 ans et a marqué 4 buts dans la compétition.', 6),
